function formatValidationErrors(errors: ErrorObject[] | null | undefined): string {
  if (!errors || errors.length === 0) return 'Validation failed';
  console.error('DEBUG: Validation errors:', JSON.stringify(errors, null, 2));
  const messages = errors.map(error => {
    const e = error as unknown as Record<string, unknown>;
    let path = (e.instancePath as string) || '';
    console.error('DEBUG: path from instancePath:', path);
    path = path.replace(/^\//g, ''); // remove leading slash from ajv path format
    console.error('DEBUG: cleaned path:', path);
    const keyword = e.keyword as string;
    const params = e.params as Record<string, unknown>;
    if (keyword === 'required') {
      const missing = params?.missingProperty;
      return `${path ? path + '.' : ''}${missing} is required`;
    }
    if (keyword === 'type') {
      const type = params?.type;
      return `${path || 'value'} must be of type ${type}`;
    }
    if (keyword === 'enum') {
      return `${path || 'value'} must match one of allowed values`;
    }
    return `${path || 'value'}: validation failed (${keyword})`;
  });
  return messages.join('; ');
}

